package medix.service;

import java.sql.SQLException;
import medix.dao.AreaDao;
import medix.dao.MedicineDao;
import medix.dao.UserDao;
import medix.model.Area;
import medix.model.Medicine;
import medix.model.MedicineForm;
import medix.model.Role;
import medix.model.User;
import medix.util.PasswordUtil;

/**
 * First-run data. Inserts go through the DAOs so ids are generated by SQLite (1, 2, 3 ...).
 */
public class SeedService {

    public static final String ADMIN_EMAIL = "admin@medix.com";
    private static final String ADMIN_PASSWORD = "admin123";

    /** Name, latitude, longitude of the 10 seeded Dhaka areas (in id order). */
    private static final Object[][] AREAS = {
        {"Dhanmondi", 23.7461, 90.3742},
        {"Mohammadpur", 23.7662, 90.3589},
        {"Farmgate", 23.7577, 90.3897},
        {"Mirpur 10", 23.8069, 90.3687},
        {"Gulshan 1", 23.7806, 90.4160},
        {"Banani", 23.7937, 90.4066},
        {"Uttara Sector 7", 23.8728, 90.3984},
        {"Bashundhara R/A", 23.8193, 90.4526},
        {"Motijheel", 23.7330, 90.4172},
        {"Lalbagh", 23.7189, 90.3880}
    };

    /**
     * 30 common medicines sold in Bangladesh (ids 1-30 on a new database):
     * brand, generic name, strength, form, manufacturer, prescription required.
     */
    private static final Object[][] MEDICINES = {
        {"Napa", "Paracetamol", "500 mg", MedicineForm.TABLET, "Beximco Pharmaceuticals", false},
        {"Napa Extra", "Paracetamol + Caffeine", "500 mg + 65 mg", MedicineForm.TABLET, "Beximco Pharmaceuticals", false},
        {"Napa", "Paracetamol", "120 mg/5 ml", MedicineForm.SYRUP, "Beximco Pharmaceuticals", false},
        {"Ace", "Paracetamol", "500 mg", MedicineForm.TABLET, "Square Pharmaceuticals", false},
        {"Seclo", "Omeprazole", "20 mg", MedicineForm.CAPSULE, "Square Pharmaceuticals", false},
        {"Sergel", "Esomeprazole", "20 mg", MedicineForm.CAPSULE, "Healthcare Pharmaceuticals", false},
        {"Losectil", "Omeprazole", "20 mg", MedicineForm.CAPSULE, "Eskayef Pharmaceuticals", false},
        {"Fexo", "Fexofenadine Hydrochloride", "120 mg", MedicineForm.TABLET, "Square Pharmaceuticals", false},
        {"Alatrol", "Cetirizine Hydrochloride", "10 mg", MedicineForm.TABLET, "Square Pharmaceuticals", false},
        {"Histacin", "Chlorpheniramine Maleate", "4 mg", MedicineForm.TABLET, "Jayson Pharmaceuticals", false},
        {"Monas", "Montelukast", "10 mg", MedicineForm.TABLET, "ACME Laboratories", true},
        {"Azithrocin", "Azithromycin", "500 mg", MedicineForm.TABLET, "Beximco Pharmaceuticals", true},
        {"Azithrocin", "Azithromycin", "200 mg/5 ml", MedicineForm.SUSPENSION, "Beximco Pharmaceuticals", true},
        {"Amodis", "Metronidazole", "400 mg", MedicineForm.TABLET, "Square Pharmaceuticals", true},
        {"Moxacil", "Amoxicillin", "500 mg", MedicineForm.CAPSULE, "Square Pharmaceuticals", true},
        {"Cef-3", "Cefixime", "200 mg", MedicineForm.CAPSULE, "Square Pharmaceuticals", true},
        {"Ceftron", "Ceftriaxone", "500 mg", MedicineForm.INJECTION, "Square Pharmaceuticals", true},
        {"Comet", "Metformin Hydrochloride", "500 mg", MedicineForm.TABLET, "Square Pharmaceuticals", true},
        {"Insulet R", "Insulin Human (Regular)", "100 IU/ml", MedicineForm.INJECTION, "Incepta Pharmaceuticals", true},
        {"Osartil", "Losartan Potassium", "50 mg", MedicineForm.TABLET, "Incepta Pharmaceuticals", true},
        {"Bislol", "Bisoprolol Fumarate", "5 mg", MedicineForm.TABLET, "Incepta Pharmaceuticals", true},
        {"Camlodin", "Amlodipine", "5 mg", MedicineForm.TABLET, "Square Pharmaceuticals", true},
        {"Atova", "Atorvastatin", "10 mg", MedicineForm.TABLET, "Beximco Pharmaceuticals", true},
        {"Rivotril", "Clonazepam", "0.5 mg", MedicineForm.TABLET, "Radiant Pharmaceuticals", true},
        {"Ventolin", "Salbutamol", "100 mcg/puff", MedicineForm.INHALER, "GlaxoSmithKline", true},
        {"Ciprocin", "Ciprofloxacin", "0.3% eye drops", MedicineForm.DROPS, "Square Pharmaceuticals", true},
        {"Betnovate", "Betamethasone Valerate", "0.1%", MedicineForm.CREAM, "GlaxoSmithKline", true},
        {"ORSaline-N", "Oral Rehydration Salts", "10.25 g/sachet", MedicineForm.POWDER, "SMC Enterprise", false},
        {"Ceevit", "Vitamin C (Ascorbic Acid)", "250 mg", MedicineForm.TABLET, "Square Pharmaceuticals", false},
        {"Calbo-D", "Calcium Carbonate + Vitamin D3", "500 mg + 200 IU", MedicineForm.TABLET, "Square Pharmaceuticals", false}
    };

    private final AreaDao areaDao = new AreaDao();
    private final UserDao userDao = new UserDao();
    private final MedicineDao medicineDao = new MedicineDao();

    public void seedIfNeeded() throws SQLException {
        if (areaDao.count() == 0) {
            seedAreas();
        }
        if (userDao.findByEmail(ADMIN_EMAIL) == null) {
            seedAdmin();
        }
        if (medicineDao.count() == 0) {
            seedMedicines();
        }
    }

    private void seedMedicines() throws SQLException {
        for (Object[] row : MEDICINES) {
            Medicine m = new Medicine();
            m.setBrandName((String) row[0]);
            m.setGenericName((String) row[1]);
            m.setStrength((String) row[2]);
            m.setForm((MedicineForm) row[3]);
            m.setManufacturer((String) row[4]);
            m.setRxRequired((Boolean) row[5]);
            medicineDao.insert(m);
        }
    }

    private void seedAreas() throws SQLException {
        for (Object[] row : AREAS) {
            Area a = new Area();
            a.setName((String) row[0]);
            a.setCity("Dhaka");
            a.setLatitude((Double) row[1]);
            a.setLongitude((Double) row[2]);
            areaDao.insert(a);
        }
    }

    private void seedAdmin() throws SQLException {
        String salt = PasswordUtil.generateSalt();
        User admin = new User();
        admin.setFullName("MediX Admin");
        admin.setEmail(ADMIN_EMAIL);
        admin.setPhone(null);
        admin.setSalt(salt);
        admin.setPasswordHash(PasswordUtil.hash(ADMIN_PASSWORD, salt));
        admin.setRole(Role.ADMIN);
        admin.setAreaId(null);
        admin.setActive(true);
        userDao.insert(admin);
    }
}
